import{_ as t,o as a,c as r,ag as n}from"./chunks/framework.Drp2S_UI.js";const m=JSON.parse('{"title":"Supported features and boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/features.md","filePath":"en/guide/features.md","lastUpdated":1792752159000}'),d={name:"en/guide/features.md"};function o(s,e,i,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="supported-features-and-boundaries" tabindex="-1">Supported features and boundaries <a class="header-anchor" href="#supported-features-and-boundaries" aria-label="Permalink to &quot;Supported features and boundaries&quot;">​</a></h1><p>This independent fork retains the document capabilities described below. Consult <a href="./option.html">options</a> and command references for exact fields, and <a href="./fork-and-differences.html">upstream differences</a> to distinguish inherited features from the new typography pipeline.</p><table tabindex="0"><thead><tr><th>Area</th><th>Available</th><th>Boundary</th></tr></thead><tbody><tr><td>Typography</td><td>HarfBuzz shaping, BiDi, complex scripts, actual face coverage and outlines</td><td>Not all scripts, styles or emoji are fully validated; font bytes are required</td></tr><tr><td>Rich text</td><td>Font/size, bold/italic, colors, highlights, scripts, decorations, headings, alignment, lists, indentation and spacing</td><td>Real style faces and metrics affect layout</td></tr><tr><td>Pages</td><td>Paginated/continuous modes, margins, columns, header/footer, numbers, borders and watermarks</td><td>Canvas pages only; DOM tools still exist</td></tr><tr><td>Tables</td><td>Row/column changes, merged cells, borders, backgrounds, alignment and page fragments</td><td>Validate complex business tables</td></tr><tr><td>Objects</td><td>Images, floating images, links, formulas, dates, tabs, page breaks and blocks</td><td>Loading, CORS and export constraints apply</td></tr><tr><td>Form controls</td><td>Text, numbers, select, radio, checkbox, date, nesting, disabling, cascades and validation</td><td>Application supplies tool UI; see control APIs</td></tr><tr><td>Interaction</td><td>Selection, caret, undo/redo, search/replace, shortcuts, menus and drag/drop</td><td>UI direction and content direction are distinct</td></tr><tr><td>Document tools</td><td>Comments, traces, areas, outline, macros, localization and modes</td><td>Verify external plugins individually</td></tr><tr><td>Fonts</td><td>TTF/OTF/WOFF/WOFF2, reports/events and automatic Bunny basic fonts</td><td>Enabled by default; offline/manual support, not full Unicode coverage</td></tr><tr><td>Export/print</td><td>JSON, HTML/text queries, Canvas PNG pages and browser image printing</td><td>No standalone SVG or native vector PDF guarantee</td></tr><tr><td>Distribution</td><td>Root ESM exports, TypeScript declarations and async readiness</td><td>No UMD, require or internal deep imports</td></tr></tbody></table><h2 id="performance-and-experimental-options" tabindex="-1">Performance and experimental options <a class="header-anchor" href="#performance-and-experimental-options" aria-label="Permalink to &quot;Performance and experimental options&quot;">​</a></h2><p><code>lab.incrementalCompute</code> defaults to false and reuses clean paragraphs, while flow, pagination and positions still run. It is not a general partial-pixel update optimization. T23/T24 regression is complete, but performance work remains and incremental mode is not necessarily faster. See <a href="./lab.html">lab options</a> and <a href="./../../guide/native-release-acceptance.html">acceptance</a>.</p><h2 id="deferred-or-unavailable" tabindex="-1">Deferred or unavailable <a class="header-anchor" href="#deferred-or-unavailable" aria-label="Permalink to &quot;Deferred or unavailable&quot;">​</a></h2><p>SVG pages and standalone SVG export remain deferred; the <a href="./../../guide/harfbuzz-svg-assessment.html">assessment</a> is a future design. There is no engine selector or legacy fallback. The package does not provide a backend server, collaborative CRDT or native Word/PDF layout engine, and it does not automatically install upstream plugins. Historical plans and future designs are not current public APIs.</p><p>Current input optimizations use the separate <code>lab.performanceProfile</code>; see <a href="./lab.html">configuration</a> and <a href="./benchmark.html">measured benchmark</a>.</p>',8)])])}const f=t(d,[["render",o]]);export{m as __pageData,f as default};
